function g({registerIndicator:c,nulls:r}){c({id:"oa-alpha-decreasing-exponential-moving-average",name:"Alpha-Decreasing Exponential Moving Average (ADEMA)",category:"Moving Averages",placement:"onchart",inputs:[],plots:[{key:"adema",type:"line",title:"ADEMA",style:{color:"#ff9800",lineWidth:2}}],calc(n){const i=new Array(n.length).fill(NaN);let a=NaN;for(let e=0;e<n.length;e++){const t=n[e].close;if(!Number.isFinite(t))continue;const o=2/(e+1),s=Number.isFinite(a)?a:t,l=o*t+(1-o)*s;i[e]=l,a=l}return{adema:r(i)}}})}export{g as default};
